# ================================================================ OA 01 clase 5
L(OA1, 5,
  use="Aprenderé a comparar dos procedimientos para un mismo cálculo y a comprobar si un resultado tiene sentido. Sirve para detectar errores de signo antes de entregar una respuesta.",
  prior=["Sé multiplicar y dividir enteros con la regla de los signos.", "Sé el orden de las operaciones."],
  explain=[
      "Un mismo cálculo se puede hacer de varias maneras. Para (−3) × (5 − 8) puedes resolver primero el paréntesis: 5 − 8 = −3 y (−3) × (−3) = 9. O puedes distribuir: (−3) × 5 + (−3) × (−8) = −15 + 24 = 9. Si los dos procedimientos dan lo mismo, el resultado es confiable.",
      "Hay tres comprobaciones útiles. Una: usar la operación inversa; si (−42) ÷ 6 = −7, entonces (−7) × 6 debe dar −42. Dos: estimar el signo con la regla de los signos y el tamaño con los valores absolutos antes de calcular. Tres: repetir el cálculo con otro procedimiento, como una suma repetida o un patrón.",
      "El orden también importa. Se resuelven primero los paréntesis y luego, de izquierda a derecha, las multiplicaciones y divisiones. Por eso (−12) ÷ (−3) × 2 = 4 × 2 = 8, y no (−12) ÷ (−6). Después vienen las sumas y restas.",
  ],
  vocab=[("distribuir", "multiplicar un número por cada término de un paréntesis"), ("comprobación", "revisión que confirma que un resultado es correcto"), ("estimar", "calcular de manera aproximada antes de hacer el cálculo exacto"), ("orden de las operaciones", "reglas que dicen qué se calcula primero"), ("valor absoluto", "distancia de un número al cero; no tiene signo")],
  worked=[
      ("Comprobar con la inversa", "Comprueba que (−7) × 6 = −42 usando una división.", ["Divido el producto por uno de los factores: (−42) ÷ 6.", "Da −7, que es el otro factor: el producto está bien."], "Correcto"),
      ("Comparar dos procedimientos", "Calcula (−3) × (5 − 8) de dos maneras.", ["Primero el paréntesis: 5 − 8 = −3 y (−3) × (−3) = 9.", "Distribuyendo: (−3) × 5 + (−3) × (−8) = −15 + 24 = 9."], "9 de las dos maneras"),
  ],
  mist=[
      ("Aceptar (−6) × 7 = −13 porque el signo es negativo.", "Se revisó el signo pero no el tamaño del resultado.", "Estima el tamaño: 6 × 7 = 42, así que el resultado es −42."),
      ("Calcular (−12) ÷ (−3) × 2 como (−12) ÷ (−6) = 2.", "Se multiplicó antes de dividir, rompiendo el orden de izquierda a derecha.", "Primero (−12) ÷ (−3) = 4 y luego 4 × 2 = 8."),
  ],
  R=[ex("Un estudiante dice que (−72) ÷ 9 = −8. ¿Qué multiplicación sirve para comprobarlo?", "(−8) × 9 = −72", "El cociente por el divisor debe dar el dividendo."),
     cx("Calcula (−4) × (−11).", "(-4)*(-11)", "Signos iguales dan producto positivo: 4 × 11 = 44."),
     cx("Calcula (−20) ÷ (−5) × 2.", "F(-20)/(-5)*2", "Se calcula de izquierda a derecha: 4 × 2.")],
  C=[cx("Calcula (−2) × (4 − 9) resolviendo primero el paréntesis.", "(-2)*(4-9)", "4 − 9 = −5 y (−2) × (−5) = 10."),
     cx("Calcula (−2) × 4 + (−2) × (−9), que es el mismo cálculo distribuido.", "(-2)*4+(-2)*(-9)", "−8 + 18 = 10, igual que con el paréntesis."),
     ex("Para estimar (−23) × 4 se redondea 23 a 20. ¿Qué resultado estimado se obtiene?", "−80", "Signos distintos dan negativo y 20 × 4 = 80; el valor exacto, −92, queda cerca."),
     ],
  A=[cx("Calcula 3 × (−6) − 4 × (−5).", "3*(-6)-4*(-5)", "−18 − (−20) = −18 + 20."),
     cx("Calcula (−6) × (−2) × (−3).", "(-6)*(-2)*(-3)", "Tres negativos dan producto negativo: 6 × 2 × 3 = 36."),
     cx("Calcula (−60) ÷ (−4) ÷ (−3).", "F(-60)/(-4)/(-3)", "Primero 15 y luego 15 ÷ (−3).")],
  Z=[ex("Dos estudiantes calculan (−5) × (3 − 7). Ana obtiene 20 y Beto obtiene −20. Revisa con el paréntesis resuelto primero y di quién tiene razón.", "Ana", "3 − 7 = −4 y (−5) × (−4) = 20."),
     ex("Clara dice que (−15) ÷ (−3) = −5 y lo comprueba con (−5) × (−3) = −15. ¿Su comprobación es correcta?", "No", "(−5) × (−3) da 15, no −15; el cociente es 5.")],
  D=[cx("Calcula 2 × (−3) × (−4) − (−6) ÷ (−2).", "2*(-3)*(-4)-F(-6)/(-2)", "El producto es 24 y el cociente es 3; luego 24 − 3."),
     ex("Un entero multiplicado por (−6) y después dividido por (−2) da 15. ¿Qué entero es?", "5", "Si x × (−6) ÷ (−2) = 15, entonces x × 3 = 15, y x = 5.")],
  ctx=[cx("Una temperatura de ejemplo baja 3 °C cada hora durante 4 horas. ¿Cuál es el cambio total? Comprueba tu respuesta dividiendo el total por 4.", "4*(-3)", "El total es −12 y la comprobación (−12) ÷ 4 = −3 devuelve el cambio de cada hora.", unit=" °C")],
  chk=[cx("Calcula (−5) × (6 − 9).", "(-5)*(6-9)", "6 − 9 = −3 y (−5) × (−3) = 15."),
       cx("Calcula (−28) ÷ 4 × (−2).", "F(-28)/4*(-2)", "Primero −7 y luego −7 × (−2)."),
       ex("¿Qué división comprueba que 8 × (−9) = −72?", "(−72) ÷ 8 = −9", "Dividir el producto por un factor debe dar el otro factor.")],
  op=("Elige una de estas expresiones: (−4) × (7 − 10) o (−6) × (3 − 8). Calcúlala de dos maneras: resolviendo primero el paréntesis y distribuyendo. Comprueba tu resultado con una división y escribe una frase que explique cuál procedimiento te pareció más seguro y por qué.",
      "Con (−4) × (7 − 10): paréntesis primero, 7 − 10 = −3 y (−4) × (−3) = 12; distribuyendo, −28 + 40 = 12. Comprobación: 12 ÷ (−4) = −3, que es el valor del paréntesis.",
      ["calcula con los dos procedimientos", "comprueba con la operación inversa", "justifica la elección con una razón matemática"],
      ["dos cálculos escritos", "división de comprobación", "frase de justificación"],
      ["dar resultados distintos y no revisar", "distribuir olvidando el signo del segundo término"],
      "Pide que revise cada signo de la distribución y que compare con el resultado del paréntesis."),
  reinforce="Calcula (−3) × (8 − 2) de las dos maneras y comprueba que da lo mismo. Luego comprueba con una división.",
  extend="Escribe dos expresiones distintas con enteros que den −24, una con multiplicación y otra con división. Comprueba cada una con la operación inversa.",
)

# ================================================================ OA 02 clase 1
L(OA2, 1,
  use="Aprenderé a representar números racionales en la recta numérica y a anticipar el signo y el tamaño de un producto o cociente antes de calcular. Sirve para saber si una respuesta es razonable.",
  prior=["Sé pasar de fracción a decimal y de decimal a fracción.", "Sé multiplicar y dividir enteros con la regla de los signos."],
  explain=[
      "Un número racional es un número que se puede escribir como fracción a/b, con a y b enteros y b distinto de 0. Los enteros (5 = 5/1), las fracciones (−3/4) y los decimales finitos (0,5 = 1/2) son racionales. En la recta numérica, los positivos están a la derecha del cero y los negativos a la izquierda: −3/4 está entre −1 y 0, a tres cuartos del cero hacia la izquierda.",
      "Para anticipar el signo se usa la regla de los enteros: signos iguales dan resultado positivo y signos distintos, negativo. Por ejemplo, (−2/3) × (3/4) será negativo, y (−0,5) ÷ (−2) será positivo. Esto sirve tanto para multiplicar como para dividir.",
      "Para anticipar el tamaño, mira el valor absoluto del factor. Si multiplicas por un número con valor absoluto menor que 1, el resultado se achica: 12 × (1/2) = 6. Si multiplicas por uno mayor que 1, se agranda. Con la división ocurre al revés: dividir por un número menor que 1 agranda el resultado, como 6 ÷ (1/2) = 12.",
  ],
  vocab=[("número racional", "número que se puede escribir como una fracción a/b con b distinto de 0"), ("fracción", "número que expresa partes de un entero, como 3/4"), ("decimal finito", "número con coma y cantidad limitada de cifras, como 0,75"), ("recta numérica", "línea donde cada número tiene su lugar"), ("valor absoluto", "distancia de un número al cero")],
  worked=[
      ("Ubicar en la recta", "Ubica −3/4 y 0,5 en una recta con marcas cada 1/4 entre −1 y 1.", ["0,5 es 1/2, o sea 2/4: está dos marcas a la derecha del cero.", "−3/4 está tres marcas a la izquierda del cero, entre −1 y 0."], "−3/4 a tres marcas a la izquierda y 0,5 a dos marcas a la derecha"),
      ("Anticipar signo y tamaño", "Antes de calcular (−2/3) × (3/4), ¿qué signo tendrá y si será mayor o menor que 2/3 en valor absoluto?", ["Los signos son distintos: el producto es negativo.", "3/4 es menor que 1, así que el producto se achica: su valor absoluto es menor que 2/3."], "Negativo y de valor absoluto menor que 2/3"),
  ],
  mist=[
      ("Ubicar −1/2 a la derecha del cero porque 1/2 está a la derecha.", "Se olvidó que el signo menos manda el número a la izquierda.", "Ubica 1/2 y luego su opuesto al otro lado del cero: −1/2."),
      ("Creer que 12 × (1/2) es mayor que 12 porque «multiplicar agranda».", "Se pensó que multiplicar siempre agranda, pero 1/2 es menor que 1.", "Multiplicar por un número entre 0 y 1 achica: 12 × 1/2 = 6."),
  ],
  R=[ex("Escribe 3/4 como decimal.", "0,75", "3 ÷ 4 = 0,75."),
     ex("Escribe −0,5 como fracción irreductible.", "−1/2", "0,5 son cinco décimos, 5/10 = 1/2, con signo menos."),
     ex("¿Cuál es mayor, −1/2 o −3/4?", "−1/2", "−1/2 está más cerca del cero, a la derecha de −3/4.")],
  C=[ex("Sin calcular, ¿el producto (−2/5) × (−3/7) es positivo o negativo?", "Positivo", "Los dos factores son negativos: signos iguales dan resultado positivo."),
     ex("Al multiplicar 20 por 3/4, ¿el resultado es A) mayor que 20 o B) menor que 20?", "B", "3/4 es menor que 1, así que el resultado se achica."),
     ex("Al dividir 6 por 1/3, ¿el resultado es A) mayor que 6 o B) menor que 6?", "A", "Dividir por un número menor que 1 agranda: cabe más de una vez en cada entero.")],
  A=[ex("Un termómetro de ejemplo marca −1,5 °C. Escribe esa temperatura como fracción mixta, es decir, un entero y una fracción.", "−1 1/2", "1,5 es 1 y 1/2, con signo negativo."),
     ex("Ordena de menor a mayor: 0,25, −1/2, −0,75 y 1/3.", "−0,75; −1/2; 0,25; 1/3", "Los negativos van primero (−0,75 está más a la izquierda que −1/2) y 0,25 = 3/12 es menor que 1/3 = 4/12."),
     ex("Entre cuáles dos enteros consecutivos está el número −2,4?", "−3 y −2", "2,4 está entre 2 y 3, así que su opuesto está entre −3 y −2.")],
  Z=[ex("Mateo dice que (−1/2) × (−1/2) es −1/4 porque «los dos tienen un menos». ¿Cuál es el signo correcto?", "Positivo", "Dos factores negativos dan un producto positivo; el resultado es 1/4."),
     ex("Sin calcular, ¿es mayor o menor que 10 el resultado de 10 ÷ 0,25?", "Mayor", "0,25 es menor que 1, así que 10 ÷ 0,25 agranda el resultado.")],
  D=[ex("¿Cuál es el punto medio de la recta numérica entre −1/2 y −1/4? Escribe ambos con denominador 8 para encontrarlo.", "−3/8", "−1/2 = −4/8 y −1/4 = −2/8; el punto medio queda a igual distancia de ambos: −3/8."),
     ex("Un número multiplicado por −1/2 da un resultado mayor que el número. ¿El número es positivo o negativo?", "Negativo", "Si el número es negativo, −1/2 de ese número es positivo y queda a la derecha; si fuera positivo, el resultado sería negativo y menor.")],
  ctx=[ex("Una receta de ejemplo usa 3/4 de taza de azúcar y se quiere hacer solo la mitad. ¿La cantidad nueva será mayor o menor que 3/4 de taza?", "Menor", "Tomar la mitad es multiplicar por 1/2, que achica la cantidad.")],
  chk=[ex("¿Qué signo tiene el cociente (−0,8) ÷ 4?", "Negativo", "Signos distintos dan cociente negativo."),
       ex("Escribe 1/5 como decimal.", "0,2", "1 ÷ 5 = 0,2."),
       ex("¿Qué número está a la misma distancia del cero que 2/3, pero a la izquierda?", "−2/3", "Es el opuesto de 2/3.")],
  op=("Dibuja una recta numérica de −2 a 2 con marcas cada 1/2. Ubica estos números: −1,5, −3/4, 0,25, 1 1/2 y 7/4. Luego elige dos de ellos, anticipa el signo de su producto y si será mayor o menor que cada factor en valor absoluto, y recién después calcúlalo.",
      "Ejemplo: elijo −3/4 y 1 1/2. El producto es negativo, su valor absoluto es 9/8, mayor que 3/4 y menor que 1 1/2. Calculo (−3/4) × (3/2) = −9/8.",
      ["ubica los cinco números en el lugar correcto", "anticipa signo y tamaño antes de calcular", "comprueba el cálculo con la anticipación"],
      ["recta dibujada", "predicción escrita", "cálculo del producto"],
      ["ubicar un negativo a la derecha del cero", "pensar que multiplicar siempre agranda"],
      "Pide que compare su predicción con el resultado y explique si coinciden."),
  reinforce="Escribe como decimal 1/4, 3/5 y −7/10. Ubícalos en una recta de −1 a 1.",
  extend="Explica con ejemplos por qué multiplicar por un número entre 0 y 1 achica el resultado y dividir por un número entre 0 y 1 lo agranda.",
)

